// ===== Fault-tolerant JSON parse helper (pasted into every Code node) =====
function tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }

function salvageArray(t, key) {
  const k = t.indexOf('"' + key + '"');
  if (k < 0) return [];
  let i = t.indexOf('[', k);
  if (i < 0) return [];
  i++;
  const out = [];
  let depth = 0, inStr = false, esc = false, start = -1;
  for (; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') { if (depth === 0) start = i; depth++; }
    else if (c === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const o = tryParse(t.slice(start, i + 1));
        if (o) out.push(o);
        start = -1;
      }
    } else if (c === ']' && depth === 0) break;
  }
  return out;
}

// Return the end index (inclusive) of the balanced {...} starting at `from`, or -1 if never closed (truncated).
function balancedEnd(t, from) {
  let depth = 0, inStr = false, esc = false;
  for (let i = from; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') inStr = true;
    else if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return i; }
  }
  return -1;
}

// Returns { data, salvaged } or null.
// Handles: model "thinking out loud" before the JSON, ```json fences, <think> blocks, trailing commas,
// smart quotes, and JSON truncated by the token limit (salvages the complete elements of arrayKey).
function parseLoose(raw, arrayKey) {
  let t = String(raw || '')
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/```json/gi, '').replace(/```/g, '').trim();

  // Candidate starts: every "{" followed by a quoted key. Prefer the ones whose first key is a known key.
  const known = /^\{\s*"(features|requirements|results|conditions|coverage_items|chunk_id|muc_tieu_tai_lieu)"/;
  const starts = [];
  const re = /\{\s*"/g;
  let m;
  while ((m = re.exec(t)) !== null) starts.push(m.index);
  starts.sort((a, b) => (known.test(t.slice(b)) ? 1 : 0) - (known.test(t.slice(a)) ? 1 : 0) || a - b);
  const ordered = starts.filter(s => known.test(t.slice(s))).concat(starts.filter(s => !known.test(t.slice(s))));

  const fixes = s => [
    s,
    s.replace(/,\s*([}\]])/g, '$1'),
    s.replace(/[“”]/g, '"').replace(/[‘’]/g, "'").replace(/,\s*([}\]])/g, '$1')
  ];

  for (const st of ordered.slice(0, 40)) {
    const end = balancedEnd(t, st);
    if (end < 0) continue;
    for (const s of fixes(t.slice(st, end + 1))) {
      const p = tryParse(s);
      if (p && typeof p === 'object' && !Array.isArray(p)) {
        if (!arrayKey || Array.isArray(p[arrayKey]) || ordered.length === 1) return { data: p, salvaged: false };
      }
    }
  }

  // Truncated output: salvage complete elements of arrayKey from the best candidate
  if (arrayKey) {
    for (const st of ordered) {
      const tail = t.slice(st);
      if (tail.indexOf('"' + arrayKey + '"') < 0) continue;
      const items = salvageArray(tail, arrayKey);
      if (items.length) {
        const mm = tail.match(/"(?:chunk_id|condition_id)"\s*:\s*"([^"]+)"/);
        const data = { [arrayKey]: items };
        if (mm) data[tail.indexOf('"chunk_id"') >= 0 ? 'chunk_id' : 'condition_id'] = mm[1];
        return { data, salvaged: true };
      }
    }
  }
  return null;
}

// Chuẩn hóa test case do AI sinh cho 1 BATCH condition; gắn metadata từ condition (không tin AI); không để rơi condition/phân vùng nào.
function processOne(first, batchArg) {
const aiText = first.output || first.text || '';
const arrOf = v => (Array.isArray(v) ? v : v ? [v] : []);

const parsed = String(aiText).trim() ? parseLoose(aiText, 'results') : null;
let results = parsed && Array.isArray(parsed.data.results) ? parsed.data.results : [];
// tương thích ngược: AI trả 1 object {condition_id, testcases} thay vì {results:[...]}
if (!results.length && parsed && Array.isArray(parsed.data.testcases)) results = [parsed.data];

// Tra cứu condition + suite_order từ Parse_conditions
const condMap = new Map();
try {
  for (const it of $('Parse_conditions').all()) {
    for (const c of arrOf(it.json.conditions)) condMap.set(c.condition_id, { cond: c, order: it.json.suite_order });
  }
} catch (e) { /* bỏ qua */ }

// Conditions of this batch are passed in by processOne(first, batchArg)
let batch = arrOf(batchArg);

let targets = batch.length ? batch : results.map(r => (condMap.get(r.condition_id) || {}).cond || { condition_id: r.condition_id || '', test_suite: 'General', test_technique: '', condition_type: '', requirement_ids: [] });
if (!targets.length) {
  throw new Error('AI_Phan_tich_Testcase trả JSON không hợp lệ và không xác định được condition.\nRAW:\n' + String(aiText).slice(0, 3000));
}
const resById = new Map(results.map(r => [r.condition_id, r]));

function toList(value) {
  if (value === null || value === undefined) return [];
  const a = Array.isArray(value) ? value : String(value).split('\n');
  return a.map(x => String(x === null || x === undefined ? '' : x).trim().replace(/^\d+\s*[\.\)]\s*/, '')).filter(x => x !== '');
}
function buildSteps(pre, steps) {
  const numbered = list => list.map((x, i) => (i + 1) + '. ' + x).join('\n');
  const p = toList(pre), s = toList(steps);
  if (p.length === 0) return numbered(s);
  return 'Pre:\n' + numbered(p) + '\nStep:\n' + numbered(s);
}
function formatResult(v) {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.filter(x => x !== null && x !== undefined && String(x).trim() !== '').map(x => String(x).trim()).join('\n');
  return String(v).trim();
}
const startsOk = s => /^(Kiểm tra|Xác minh|Validate)\b/i.test(s);

function fallbackTC(cond, label) {
  const steps = ['Đăng nhập thành công', 'Truy cập chức năng thuộc "' + (cond.test_suite || '') + '"']
    .concat(arrOf(label ? [label] : cond.test_data_hint).map(h => 'Chuẩn bị/nhập dữ liệu: ' + h))
    .concat(cond.context ? ['Thực hiện thao tác theo ngữ cảnh: ' + cond.context] : [])
    .concat(['Quan sát và đối chiếu kết quả mong muốn']);
  const exp = arrOf(cond.expected_behavior_hint);
  const lines = exp.length ? exp.join('\n- ') : 'N/A (Tài liệu chưa đặc tả)';
  return {
    test_suite: cond.test_suite,
    muc_dich: 'Kiểm tra ' + (cond.condition || '') + (label ? ' - ' + label : ''),
    dieu_kien_tien_quyet: cond.preconditions || [],
    cac_buoc: steps,
    ket_qua_mong_muon: [steps.length + '. - ' + lines],
    _fallback: true
  };
}

function buildRows(cond, r) {
  let tcs = r && Array.isArray(r.testcases) ? r.testcases : [];
  const plan = r && Array.isArray(r.phan_vung_ap_dung) ? r.phan_vung_ap_dung : [];
  const notes = [];
  if (!tcs.length) notes.push(parsed && parsed.salvaged ? 'JSON test case bị cắt cụt, condition này chưa được AI sinh' : 'AI không trả test case hợp lệ cho condition này');

  // Condition/phân vùng chưa có TC -> sinh TC dự phòng để không rơi coverage
  if (!tcs.length) {
    const labels = plan.length ? plan : arrOf(cond.test_data_hint);
    tcs = labels.length ? labels.map(l => fallbackTC(cond, l)) : [fallbackTC(cond, '')];
  } else if (plan.length > tcs.length) {
    notes.push('AI lập kế hoạch ' + plan.length + ' phân vùng nhưng chỉ sinh ' + tcs.length + ' TC');
    for (let i = tcs.length; i < plan.length; i++) tcs.push(fallbackTC(cond, plan[i]));
  }

  const ctxOrder = (condMap.get(cond.condition_id) || {}).order;
  const order = cond.suite_order !== undefined ? cond.suite_order : (ctxOrder !== undefined ? ctxOrder : 9999);
  const srcRef = arrOf(cond.requirement_ids).join(', ');
  const tag = '[Kỹ thuật: ' + (cond.test_technique || 'N/A') + '] [Loại: ' + (cond.condition_type || 'N/A') + ']' + (srcRef ? ' [Nguồn: ' + srcRef + ']' : '');
  const gapNote = cond.requirement_gap ? ' [Thiếu đặc tả: ' + cond.requirement_gap + ']' : '';

  return tcs.map(tc => {
    let purpose = String(tc.muc_dich || '').trim();
    if (purpose && !startsOk(purpose)) purpose = 'Kiểm tra ' + purpose.charAt(0).toLowerCase() + purpose.slice(1);
    const review = tc._fallback || cond._generated ? ' [CẦN RÀ SOÁT: ' + (notes.join('; ') || 'nội dung sinh dự phòng, chưa được AI chi tiết hóa') + ']' : '';
    return {
      json: {
        test_suite: cond.test_suite || tc.test_suite || 'General',
        suite_order: order,
        condition_id: cond.condition_id || '',
        muc_dich: purpose,
        cac_buoc: buildSteps(tc.dieu_kien_tien_quyet, tc.cac_buoc),
        ket_qua_mong_muon: formatResult(tc.ket_qua_mong_muon),
        ghi_chu: tag + gapNote + review
      }
    };
  });
}

const out = [];
for (const cond of targets) {
  const r = resById.get(cond.condition_id) || (targets.length === 1 && results.length === 1 ? results[0] : null);
  out.push(...buildRows(cond, r));
}
return out.filter(r => r.json.muc_dich && r.json.cac_buoc);
}

// AI node output is index-aligned with Make_batches (1 output item per batch, errors included)
const batches = $('Make_batches').all();
const all = [];
$input.all().forEach((it, idx) => {
  const b = batches[idx] ? batches[idx].json.conditions : [];
  all.push(...processOne(it.json, b));
});
return all;

// Lấy data từ API Figma trả về
const figmaData = $input.first().json;
const documentNode = figmaData.document;

// Lấy thông tin bài toán cũ truyền sang để không bị mất kết nối
const baiToanGoc = $("Switch").item.json; 

// Đệ quy moi móc toàn bộ Text trên giao diện
function extractText(node) {
    let texts = [];
    if (node.type === "TEXT" && node.characters) {
        texts.push(`[${node.name}]: ${node.characters.replace(/\n/g, ' ')}`); 
    }
    if (node.children) {
        for (let child of node.children) {
            texts = texts.concat(extractText(child));
        }
    }
    return texts;
}

const allExtractedText = extractText(documentNode);

// Trả về biến 'data' giống hệt định dạng của nhánh Google Docs
return {
    json: {
        ...baiToanGoc, // Giữ lại tên Bài toán, Link Testcase...
        "data": "DỮ LIỆU GIAO DIỆN TỪ FIGMA:\n" + allExtractedText.join("\n")
    }
};

// 1. Lấy toàn bộ dữ liệu từ node trước đó (nhánh "Chưa làm")
const items = $input.all();
const newItems = [];

// 2. Duyệt qua từng bài toán
for (let i = 0; i < items.length; i++) {
    const item = items[i].json;
    const rawUrls = item["URL"] || "";

    // 3. Tách link: Xử lý cắt chuỗi bằng dấu phẩy (,) hoặc dấu xuống dòng (\n)
    const urlArray = rawUrls.split(/[,\n]+/);

    // 4. Tạo ra các item lẻ cho từng link để node sau dễ đọc
    for (let j = 0; j < urlArray.length; j++) {
        const singleUrl = urlArray[j].trim();

        // Nếu link không bị rỗng thì mới đẩy vào mảng
        if (singleUrl !== "") {
            newItems.push({
                json: {
                    ...item,             // Giữ lại toàn bộ data cũ (Tên bài toán, Link Testcase...)
                    "url_le": singleUrl  // Tạo thêm 1 trường mới chỉ chứa 1 link duy nhất để đọc
                }
            });
        }
    }
}

// 5. Trả về danh sách các link lẻ đã được tách
return newItems;

const items = $input.all();
const grouped = {};

// Dọn rác khoảng trắng: tài liệu Word/Docs crawl về chứa hàng chục nghìn ký tự \r \n \t lặp lại
// -> phình số token khiến AI bị "Request timed out". Làm sạch trước khi gom/lưu/gửi AI.
function cleanDoc(s) {
  return String(s || '')
    .replace(/\r\n?/g, '\n')
    .replace(/\u00a0/g, ' ')
    .split('\n')
    .map(l => l.replace(/[ \t]+/g, ' ').trim())
    .join('\n')
    .replace(/\n{2,}/g, '\n')   // bỏ toàn bộ dòng trống thừa
    .trim();
}

items.forEach(item => {
    const json = item.json;
    const key = json['Bài toán'] || 'Default'; // Gom nhóm theo Tên bài toán

    if (!grouped[key]) {
        grouped[key] = { ...json, data: [] };
    }

    const txt = cleanDoc(json.data);
    if (txt) grouped[key].data.push(txt);
});

const results = [];
for (const key in grouped) {
    const finalItem = grouped[key];
    finalItem.data = finalItem.data.join("\n\n--- TÀI LIỆU TIẾP THEO ---\n\n");
    results.push({ json: finalItem });
}

return results;

const items = $input.all();
const baiToanGoc = items[0].json; 

let textContent = `\n\n--- DANH SÁCH API CẦN KIỂM THỬ (BẮT BUỘC ĐỌC) ---\n`;

items.forEach((item) => {
    const data = item.json;
    // Bắt đúng các key từ file Google Sheets của anh
    const tenApi = data["Danh sách api sử dụng "] || "";
    const endpoint = data["col_3"] || data["Đầu api"] || "";
    const moTa = data["col_4"] || data["Mô tả"] || "";

    // Chỉ lấy những dòng có chứa đường link http/api
    if (endpoint.includes("http") || endpoint.includes("api/")) {
        textContent += `\n* Tên API: ${tenApi}\n  - Endpoint: ${endpoint}\n  - Mô tả bổ sung: ${moTa}\n`;
    }
});

return {
    json: {
        "Bài toán": baiToanGoc["Bài toán"],
        "Link Testcase": baiToanGoc["Link Testcase"],
        "Trạng thái": baiToanGoc["Trạng thái"],
        "url_le": baiToanGoc["url_le"],
        "data": textContent
    }
};

// 1. Lấy dữ liệu từ con AI
let text = $('AI_phan_tich_bai_toan').first().json.output || $('AI_phan_tich_bai_toan').first().json.text || "";

// 2. Dọn dẹp thẻ markdown bọc ngoài
text = text.replace(/^```(json|markdown|md)?/im, "");
text = text.replace(/```$/im, "");

// 3. Ép kiểu JSON và GỘP THÀNH 1 ĐOẠN VĂN BẢN
let combinedText = "";
try {
  let parsedData = JSON.parse(text.trim());

  // Gộp các phần lại và tự động thêm tiêu đề cho đẹp
  if (parsedData.muc_tieu_tai_lieu) 
      combinedText += "1. MỤC TIÊU TÀI LIỆU\n" + parsedData.muc_tieu_tai_lieu + "\n\n";

  if (parsedData.he_thong_va_api) 
      combinedText += "2. CÁC HỆ THỐNG VÀ API\n" + parsedData.he_thong_va_api + "\n\n";

  if (parsedData.luong_nghiep_vu) 
      combinedText += "3. LUỒNG NGHIỆP VỤ CHÍNH\n" + parsedData.luong_nghiep_vu + "\n\n";

  if (parsedData.bang_du_lieu) 
      combinedText += "4. CÁC BẢNG DỮ LIỆU\n" + parsedData.bang_du_lieu + "\n\n";

  if (parsedData.test_scenarios) 
      combinedText += "5. KỊCH BẢN KIỂM THỬ (TEST SCENARIOS)\n" + parsedData.test_scenarios + "\n\n";

  if (parsedData.rui_ro_va_cau_hoi) 
      combinedText += "6. RỦI RO / ĐIỂM CHƯA RÕ\n" + parsedData.rui_ro_va_cau_hoi + "\n\n";

  // Đề phòng trường hợp AI trả về key lạ, cứ có nội dung là in ra hết
  if (combinedText === "") {
      for (const key in parsedData) {
          combinedText += `${key.toUpperCase()}:\n${parsedData[key]}\n\n`;
      }
  }

} catch (error) {
  // Nếu lỗi (AI không trả JSON chuẩn), lấy luôn cục chữ nguyên bản của AI
  combinedText = "Nội dung phân tích:\n\n" + text;
}

// 4. TRẢ VỀ ĐÚNG 1 ITEM ĐỂ GOOGLE DOCS IN 1 LẦN
return [{
  json: {
    final_text: combinedText.trim()
  }
}];

const sheetsData = $input.first().json.sheets;
// Móc lại thông tin Bài toán gốc từ node Switch1
const baiToanGoc = $("phân_luồng_tài_liệu").first().json; 

const results = [];
for (const sheet of sheetsData) {
    results.push({
        json: {
            ...baiToanGoc,
            sheet_name: sheet.properties.title
        }
    });
}
return results;

const body = $input.first().json.body;
const newItems = [];

// Trường hợp 1: Nhận mảng từ nút "Chạy các bài đã chọn"
if (body.danhSachBaiToan && Array.isArray(body.danhSachBaiToan)) {
  body.danhSachBaiToan.forEach(task => {
    newItems.push({
      json: {
        baiToan: task,
        promptAI1: body.promptAI1,
        promptAI2: body.promptAI2
      }
    });
  });
} 
// Trường hợp 2: Nhận chuỗi từ nút "Play" của 1 bài đơn lẻ
else if (body.baiToan) {
  newItems.push({
    json: {
      baiToan: body.baiToan,
      promptAI1: body.promptAI1,
      promptAI2: body.promptAI2
    }
  });
}

return newItems;

parameters.text:
=You are a Senior Business Analyst and QA Architect.

TASK
Read the ENTIRE input document and extract structured requirements at a DETAILED level, sufficient for later steps to generate test cases using these techniques: Equivalence Partitioning, Boundary Value Analysis, Decision Table, State Transition, Negative testing, Regression.
- Do NOT generate Test Cases, Test Scenarios or Test Steps.
- Be COMPLETE but COMPACT: do not skip any rule/field/state and do not merge different rules, but every string is at most ~30 words and the SAME content must NOT be repeated under several keys (if it is already in business_rules, do not copy it into validation/exceptions). Leave the "context" key of each requirement as an empty string.

DOCUMENT PART (the document was split into parts to keep each answer short)
You are reading part {{ $json.chunk_index }} of {{ $json.total_chunks }}. Extract ONLY what is stated in this part.
- Do NOT write an "ambiguities" entry just because a detail is not in this part (it may be in another part). Only report real contradictions/gaps visible inside this part.
- Use feature_id/requirement_id numbering starting from 001 inside this part (they will be renumbered when merged). If this part continues a flow of the previous part, reuse the same feature_name.
- Create the extra regression feature (rule 8) ONLY if this is the last part ({{ $json.is_last_chunk }}); otherwise do not create it, but still fill "change_scope" for this part.

SINGLE SOURCE OF INFORMATION
You may only use (1) the document content and (2) the "ADDITIONAL USER REQUIREMENTS" section at the end. Do NOT infer or invent any Business Rule, Validation, API, table/column, status, permission, message or error code. If a detail is missing, write exactly: "Tài liệu hiện tại chưa đặc tả phần này." and also add it to "ambiguities".

EXTRACTION RULES (review every item, skip nothing):
1. INPUT FIELDS: for each field record (when the document states it): data type, required/optional, min/max length, format, valid value domain, default value, dependency on other fields. Put them in "inputs" and "requirements[].validation". If the document gives concrete values/examples, keep them VERBATIM.
2. BRANCHING RULES: every IF/ELSE branch is its own "business_rules" entry (including the NOT-satisfied branch and the default branch). When a decision depends on 2 or more conditions, also build "decision_tables" listing every combination the document allows.
3. STATES: for each entity with a status (e.g. STATUS = x) record all values stated, their meaning and transition conditions; state clearly which statuses are VALID for performing the business operation and which are NOT.
4. INTEGRATIONS / SYSTEM CALLS: every call to another system or API goes into "integrations": system, endpoint, trigger condition, every request payload field, success response, every error code/error response, timeout/error behavior, where the log/audit is stored (table, file) ONLY if the document states it. Also state the conditions under which it must NOT be called.
5. DATA CHANGES: for each scenario (success, reject, cancel, error, no change) write "table.column: value before -> value after" into "data_objects[].data_change". A scenario that must not change data must say "không thay đổi".
6. MESSAGES/LABELS/POPUPS: keep VERBATIM in "expected_behavior" or "error_handling".
7. EXCEPTIONS: reject, cancel, dispute, system error, repeated action, duplicate/existing data, not found... only when the document states them -> "exceptions".
8. CHANGE SCOPE & REGRESSION: identify which parts are modified/new (changed) and which are NOT modified but pass through the same API/module/table (unchanged_but_impacted) -> "change_scope". If any exist, add one extra feature named "Hồi quy các luồng đi qua <API/module name>" with requirements describing the behavior that must stay unchanged. If the document does not mention any impacted flow, write it in ambiguities and do NOT invent flow names.
9. SPLIT FEATURES BY BUSINESS PROCESS: each feature is one step/screen/flow (e.g. Input screen -> Duplicate check -> External system call -> Approval -> Post-approval processing -> Exceptions). Set "flow_order" = 1..n in the real chronological processing order. Each feature holds at most about 8 requirements; if more, split into sub-features by step. Do NOT put the whole document in one feature.
10. Each requirement is one independent, verifiable behavior. Merge only when two requirements are completely identical.
11. Keep technical names unchanged (API, endpoint, table, column, parameter, status, error code, job).
12. All string values in the JSON are written in natural Vietnamese with a professional BA style (except technical names, which stay unchanged).

JSON OUTPUT STRUCTURE (existing keys must be kept; keys with no data are an empty array / null):
{
  "features": [
    { "feature_id": "FEAT001", "feature_name": "", "description": "", "flow_order": 1 }
  ],
  "requirements": [
    {
      "requirement_id": "REQ001",
      "feature_id": "FEAT001",
      "type": "Screen name or business flow",
      "requirement": "",
      "context": "",
      "preconditions": [],
      "expected_behavior": "",
      "related_api": [],
      "related_fields": [],
      "related_state": [],
      "validation": [],
      "error_handling": []
    }
