// Gom testcase vừa sinh -> bản ghi bộ nhớ + chia lô <= 100 để gọi embedding
const MODEL = 'models/gemini-embedding-001', DIM = 768, BATCH = 100;
const s = v => (Array.isArray(v) ? v.join('\n') : String(v ?? '')).trim();
function hash(str) { // cyrb53 - không cần module ngoài
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}
let p = {};
try { p = $('Update_link_sheet_TC').first().json || {}; } catch (e) {}
const problemId = String(p.problem_id || '');
const title = p['Bài toán'] || '';

const seen = new Set();
const records = [];
for (const it of $input.all()) {
  const r = it.json || {};
  if (r.row_type !== 'testcase' || !(r.muc_dich || r.cac_buoc)) continue;
  const content = {
    muc_dich: s(r.muc_dich), cac_buoc: s(r.cac_buoc),
    ket_qua_mong_muon: s(r.ket_qua_mong_muon), ghi_chu: s(r.ghi_chu)
  };
  const h = hash([r.test_suite, content.muc_dich, content.cac_buoc, content.ket_qua_mong_muon].join('||'));
  if (seen.has(h)) continue;
  seen.add(h);
  records.push({
    kind: 'testcase', problem_id: problemId, problem_title: title,
    test_suite: s(r.test_suite) || 'General', content,
    embed_text: (s(r.test_suite) + ' | ' + content.muc_dich).slice(0, 1000),
    content_hash: h
  });
}
if (!problemId || !records.length) return [{ json: { records: [], requests: [] } }];

const out = [];
for (let i = 0; i < records.length; i += BATCH) {
  const part = records.slice(i, i + BATCH);
  out.push({ json: {
    records: part,
    requests: part.map(x => ({
      model: MODEL, content: { parts: [{ text: x.embed_text }] },
      taskType: 'SEMANTIC_SIMILARITY', outputDimensionality: DIM
    }))
  } });
}
return out;

