  const embs = (it.json && it.json.embeddings) || [];
  const rows = [];
  recs.forEach((r, k) => {
    const v = embs[k] && embs[k].values;
    if (Array.isArray(v) && v.length === 768) rows.push({ ...r, embedding: '[' + v.join(',') + ']' });
  });
  out.push({ json: { rows, skipped: recs.length - rows.length } });
});
return out.length ? out : [{ json: { rows: [], skipped: 0 } }];

